-- T0 FROZEN SCHEMA (PROPOSAL — pending owner confirmation).
-- Workers: do NOT edit this file. Apply it as-is.
-- After any migration that touches existing rows:
--   INSERT INTO messages_fts(messages_fts) VALUES('rebuild');
-- Never run VACUUM: it can renumber rowids and desync the FTS index.

PRAGMA journal_mode=WAL;

CREATE TABLE settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL);

CREATE TABLE sessions (sid TEXT PRIMARY KEY, sess_json TEXT NOT NULL, expires_at TEXT NOT NULL);

CREATE TABLE folders (id TEXT PRIMARY KEY, parent_id TEXT, display_name TEXT NOT NULL, well_known TEXT);

CREATE TABLE sync_state (
  folder_id TEXT PRIMARY KEY,
  delta_link TEXT,
  resume_link TEXT,
  window_days INTEGER,
  last_sync_at TEXT,
  last_full_sync_at TEXT,
  status TEXT,
  error TEXT
);

CREATE TABLE messages (
  id TEXT PRIMARY KEY,
  conversation_id TEXT,
  folder_id TEXT NOT NULL,
  subject TEXT,
  from_address TEXT,
  from_name TEXT,
  to_json TEXT,
  cc_json TEXT,
  received_at TEXT,
  sent_at TEXT,
  effective_at TEXT,
  is_read INTEGER,
  importance TEXT,
  has_attachments INTEGER,
  flag_status TEXT,
  categories_json TEXT,
  body_preview TEXT,
  inference_class TEXT,
  web_link TEXT,
  is_draft INTEGER,
  is_from_me INTEGER,
  base_score INTEGER,
  score INTEGER,
  score_breakdown_json TEXT,
  auto_categories_json TEXT,
  scored_at TEXT,
  last_seen_sync TEXT
);

CREATE INDEX ix_msg_folder_received ON messages(folder_id, received_at DESC);
CREATE INDEX ix_msg_conv ON messages(conversation_id, effective_at);
CREATE INDEX ix_msg_unread ON messages(is_read, received_at);
CREATE INDEX ix_msg_score ON messages(score DESC);
CREATE INDEX ix_msg_from ON messages(from_address);

CREATE VIRTUAL TABLE messages_fts USING fts5(
  subject, from_address, from_name, body_preview,
  content=messages, content_rowid=rowid
);

CREATE TRIGGER messages_ai AFTER INSERT ON messages BEGIN
  INSERT INTO messages_fts(rowid, subject, from_address, from_name, body_preview)
  VALUES (new.rowid, new.subject, new.from_address, new.from_name, new.body_preview);
END;

CREATE TRIGGER messages_ad AFTER DELETE ON messages BEGIN
  INSERT INTO messages_fts(messages_fts, rowid, subject, from_address, from_name, body_preview)
  VALUES ('delete', old.rowid, old.subject, old.from_address, old.from_name, old.body_preview);
END;

CREATE TRIGGER messages_au AFTER UPDATE ON messages BEGIN
  INSERT INTO messages_fts(messages_fts, rowid, subject, from_address, from_name, body_preview)
  VALUES ('delete', old.rowid, old.subject, old.from_address, old.from_name, old.body_preview);
  INSERT INTO messages_fts(rowid, subject, from_address, from_name, body_preview)
  VALUES (new.rowid, new.subject, new.from_address, new.from_name, new.body_preview);
END;

CREATE TABLE conversation_state (
  conversation_id TEXT PRIMARY KEY,
  dismissed_waiting INTEGER NOT NULL DEFAULT 0,
  dismissed_at TEXT,
  last_message_id TEXT
);

CREATE TABLE vip (
  id INTEGER PRIMARY KEY,
  pattern TEXT NOT NULL UNIQUE,
  kind TEXT NOT NULL,
  label TEXT,
  group_name TEXT
);

CREATE TABLE rules (
  id INTEGER PRIMARY KEY,
  name TEXT,
  position INTEGER,
  enabled INTEGER,
  conditions_json TEXT,
  actions_json TEXT
);

CREATE TABLE action_log (
  id INTEGER PRIMARY KEY,
  batch_id TEXT,
  ts TEXT,
  message_id TEXT,
  action TEXT,
  params_json TEXT,
  status TEXT,
  error TEXT,
  undo_json TEXT
);

CREATE TABLE ai_results (
  message_id TEXT PRIMARY KEY,
  content_hash TEXT,
  model TEXT,
  result_json TEXT,
  created_at TEXT
);
